export async function fetchEntityData(id) {
  try {
    const formattedId = String(id).padStart(4, '0');
    const records = { '0001': 'Alice', '0002': 'Bob' };
    const entries = Object.entries(records);
    return { formattedId, entries };
  } catch (error) {
    return { error: 'Failed' };
  }
}

